import {fmtDate,parseDate,plusDays,mins,hhmm,overlaps,isWorkday,windowsFor,slotsFor,formatMoney,escapeHtml as e} from './rules.mjs';
const $=s=>document.querySelector(s), root=$('#app');
let db=null, user=null, profile=null, isAdmin=false, busy=false, page='booking', loginMode='signin', modal=null;
let offlineClients=[];
let settings={cancel_hours:24,business_phone:'',business_email:''}, treatments=[], clients=[], appointments=[], schedules=[], monthStats=[], slots=[], selectedTreatment='', chosenSlot='', selectedDate=fmtDate(new Date()), shownMonth=selectedDate.slice(0,7)+'-01', scheduleDate=selectedDate, search='', selectedDay=selectedDate, activeWeek=selectedDate, calendarMode='month';
let loadingSeq=0, authError='', syncing=false, saving=false, moreOpen=false;
let waitlist=[], statsRange='month', dayFocus=fmtDate(new Date()), realtimeChannel=null, realtimeTimer=null, lastSyncAt=null, notifyFilter='all', customerSearch='';
const cfg=window.LUR_CONFIG||{};
const money=formatMoney;
const errorText=err=>{const s=String(err?.message||err||'Error desconocido');return s.replace(/\b[a-z0-9]{20,}\b/ig,'[identificador]').slice(0,260)};
function toast(t){$('#toast').innerHTML=`<div class="toast">${e(t)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').innerHTML='',5500)}
function setLoading(message='Sincronizando con Supabase…'){root.innerHTML=`<div class="loading"><div class="spin"></div><h1>masajes LUR</h1><p>${e(message)}</p></div>`}
function btn(a,label,extra=''){return `<button type="button" class="ghost compact" data-action="${a}" ${extra}>${label}</button>`}
const today=()=>fmtDate(new Date());
const isoLocal=stamp=>String(stamp||'').slice(0,16);
const activeTreatments=()=>treatments.filter(t=>t.active);
const currentTreatment=()=>treatments.find(t=>t.id===selectedTreatment)||activeTreatments()[0];
const trName=id=>treatments.find(x=>x.id===id)?.name||'Tratamiento';
const customer=id=>clients.find(x=>x.id===id)||offlineClients.find(x=>x.id===id);
const appointmentClient=a=>a.offline_client_id||a.client_id;
const displayName=a=>customer(appointmentClient(a))?.full_name||a.guest_name||'Cliente';
const dayAppts=d=>appointments.filter(a=>a.day===d&&a.status!=='cancelled').sort((a,b)=>a.start_time.localeCompare(b.start_time));
const aTime=a=>String(a.start_time||'').slice(0,5);
const euDate=d=>parseDate(d)?.toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'})||d;
const dateTitle=d=>parseDate(d)?.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'})||d;
const monthTitle=d=>parseDate(d)?.toLocaleDateString('es-ES',{month:'long',year:'numeric'})||d;
function addMonth(d,n){const x=parseDate(d);x.setDate(1);x.setMonth(x.getMonth()+n);return fmtDate(x)}
function getSchedule(d){const r=schedules.find(x=>x.day===d);return windowsFor(d,r?.windows)}
function adminSlots(d,t){if(!t)return[];const w=getSchedule(d);return slotsFor(w,t.duration_minutes,t.buffer_minutes).map(time=>{const start=mins(time),end=start+t.duration_minutes+t.buffer_minutes;return {slot:time,available:!dayAppts(d).some(a=>overlaps(start,end,mins(aTime(a)),mins(aTime(a))+a.duration_minutes+a.buffer_minutes))}})}
function readableError(err){const s=errorText(err);if(/duplicate|exclusion|conflict|ocupad|horario/i.test(s))return 'El horario no está disponible. Actualiza y elige otro.';return s}
async function request(q){const {data,error}=await q;if(error)throw error;return data}
async function init(){
 if(!cfg.supabaseUrl||!cfg.supabasePublishableKey){root.innerHTML=`<div class="login-shell"><div class="login-card"><div class="brand"><span class="flower">✿</span>masajes LUR</div><h2>Falta configurar Supabase</h2><p class="subtle">Edita <code>config.js</code> e introduce únicamente la URL del proyecto y la clave pública. A continuación publica estos archivos en GitHub Pages.</p><p class="help">La aplicación no permite crear reservas desconectada para evitar datos distintos entre dispositivos.</p></div></div>`;return}
 if(!window.supabase?.createClient){root.innerHTML='<div class="login-shell"><div class="login-card"><h2>Error de conexión</h2><p>No se ha podido cargar la librería de Supabase. Comprueba Internet y recarga la página.</p></div></div>';return}
 try{db=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});
 db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){stopRealtime();user=null;profile=null;isAdmin=false;renderAuth()} });
 const {data,error}=await db.auth.getSession();if(error)throw error;
 if(data.session?.user)await boot(data.session.user);else renderAuth();
 window.addEventListener('focus',()=>{if(user&&!busy&&!modal)refreshQuiet()});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&user&&!busy&&!modal)refreshQuiet()});
 }catch(err){authError=readableError(err);renderAuth()}
}
async function boot(u){user=u;await loadData(true);setupRealtime()}
async function loadData(showSpinner=false){if(!user)return;const seq=++loadingSeq;busy=true;if(showSpinner)setLoading();
 try{
  const adminRows=await request(db.from('lur_admins').select('user_id').eq('user_id',user.id));
  isAdmin=adminRows.length>0;
  const [p,t,a,c,s,st,w,oc]=await Promise.all([
   request(db.from('lur_profiles').select('id,full_name,email,phone').eq('id',user.id).single()),
   request(db.from('lur_treatments').select('*').order('name')),
   request(db.from('lur_appointments').select('*').order('day',{ascending:false}).order('start_time',{ascending:false}).limit(3000)),
   isAdmin?request(db.from('lur_profiles').select('id,full_name,email,phone,created_at').order('full_name').limit(3000)):Promise.resolve([]),
   isAdmin?request(db.from('lur_schedules').select('*').order('day').limit(3000)):Promise.resolve([]),
   request(db.from('lur_business_settings').select('*').eq('id',1).single()),
   request(db.from('lur_waitlist').select('*').order('created_at',{ascending:false}).limit(2000)),
   isAdmin?request(db.from('lur_offline_clients').select('*').order('full_name').limit(3000)):Promise.resolve([])
  ]);
  if(seq!==loadingSeq)return;
  profile=p;treatments=t;appointments=a;clients=c;offlineClients=oc;schedules=s;settings=st;waitlist=w;lastSyncAt=new Date();
  if(!activeTreatments().some(x=>x.id===selectedTreatment))selectedTreatment=activeTreatments()[0]?.id||'';
  if(isAdmin&&page==='booking')page='dashboard';
  if(!isAdmin&&!['booking','mine','profile','help','waiting'].includes(page))page='booking';
  await fetchCalendar();await fetchSlots();
  busy=false;render();
 }catch(err){busy=false;root.innerHTML=`<div class="login-shell"><div class="login-card"><h2>No se pudieron sincronizar los datos</h2><p class="subtle">Para evitar reservas incorrectas hemos bloqueado la agenda hasta recuperar los datos.</p><div class="auth-error">${e(readableError(err))}</div><div class="actions"><button class="button" data-action="retry">Reintentar</button><button class="ghost" data-action="logout">Cerrar sesión</button></div></div></div>`}
}
async function refreshQuiet(){if(!user||busy||saving||modal)return;await loadData(false)}
function setupRealtime(){
 if(!db||!user)return;
 if(realtimeChannel)db.removeChannel(realtimeChannel);
 // Realtime entrega solo filas autorizadas con RLS; no se muestran datos ajenos.
 const changed=()=>{clearTimeout(realtimeTimer);realtimeTimer=setTimeout(()=>{if(!document.hidden)refreshQuiet()},850)};
 realtimeChannel=db.channel('lur-v4-'+user.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'lur_calendar_events'},changed).on('postgres_changes',{event:'*',schema:'public',table:'lur_appointments'},changed)
 .on('postgres_changes',{event:'*',schema:'public',table:'lur_treatments'},changed)
 .on('postgres_changes',{event:'*',schema:'public',table:'lur_schedules'},changed)
 .subscribe();
}
function stopRealtime(){clearTimeout(realtimeTimer);if(db&&realtimeChannel)db.removeChannel(realtimeChannel);realtimeChannel=null}

async function fetchCalendar(){if(!selectedTreatment)return monthStats=[];const {data,error}=await db.rpc('lur_month_availability',{p_month:shownMonth,p_treatment:selectedTreatment});if(error)throw error;monthStats=data||[]}
async function fetchSlots(){if(!selectedTreatment){slots=[];return}const {data,error}=await db.rpc('lur_availability',{p_day:selectedDate,p_treatment:selectedTreatment});if(error)throw error;slots=data||[];if(!slots.some(x=>x.slot===chosenSlot&&x.available))chosenSlot=''}
async function reload(){await loadData(true)}
function renderAuth(){const signup=loginMode==='signup',recovery=loginMode==='recover';root.innerHTML=`<div class="login-shell"><div class="login-card"><div class="brand"><span class="flower">✿</span>masajes LUR</div><h2>${signup?'Crea tu cuenta':recovery?'Recuperar contraseña':'Te damos la bienvenida'}</h2><p class="subtle">${signup?'Regístrate para reservar tu masaje en pocos pasos.':recovery?'Recibirás un enlace para restablecer tu contraseña.':'Accede para ver la agenda y tus reservas.'}</p>${authError?`<div class="auth-error">${e(authError)}</div>`:''}${!recovery?`<div class="toggle"><button data-action="auth-mode" data-mode="signin" class="${!signup?'selected':''}">Entrar</button><button data-action="auth-mode" data-mode="signup" class="${signup?'selected':''}">Crear cuenta</button></div>`:''}<form id="auth-form">${signup?`<label class="field">Nombre y apellidos<input name="name" maxlength="120" required autocomplete="name"></label><label class="field">Teléfono<input name="phone" type="tel" maxlength="40" required autocomplete="tel"></label>`:''}<label class="field">Correo electrónico<input name="email" type="email" required autocomplete="email"></label>${!recovery?`<label class="field">Contraseña<input name="password" type="password" minlength="8" required autocomplete="${signup?'new-password':'current-password'}"></label>`:''}<button class="button" style="width:100%" type="submit">${signup?'Registrarme':recovery?'Enviar enlace':'Entrar'}</button></form><div class="actions" style="margin-top:14px">${recovery?btn('auth-mode','Volver al inicio','data-mode="signin"'):btn('auth-mode','¿Olvidaste la contraseña?','data-mode="recover"')}</div><p class="help" style="margin-top:18px">Tus datos personales son privados. Las reservas se confirman automáticamente si el horario sigue libre.</p></div></div>`}
function title(text,desc,actions=''){return `<div class="top"><div><div class="eyebrow">MASAJES LUR · ${isAdmin?'ADMINISTRACIÓN':'ESPACIO PERSONAL'}</div><h1>${text}</h1>${desc?`<p class="small" style="margin-top:8px">${desc}</p>`:''}</div><div class="top-right">${actions}<span class="pill" title="Datos cargados desde Supabase">● Sincronizado</span></div></div>`}
const adminPages=[['dashboard','Inicio','⌂'],['daily','Hoy','◷'],['calendar','Agenda','▦'],['booking','Nueva cita','＋'],['clients','Clientes','♙'],['schedule','Horarios','◷'],['treatments','Tratamientos','✿'],['payments','Cobros','€'],['insights','Estadísticas','▥'],['waitlist','Espera','♡'],['settings','Ajustes','⚙'],['profile','Mi perfil','♙']];
const clientPages=[['booking','Reservar','▦'],['waiting','Lista espera','♡'],['mine','Mis citas','♡'],['profile','Mi perfil','♙'],['help','Ayuda','?']];
function nav(){return (isAdmin?adminPages:clientPages).map(([p,n,i])=>`<button data-action="go" data-page="${p}" class="${page===p?'current':''}"><span>${i}</span>${n}</button>`).join('')}
// La navegación de administración móvil se reparte entre cuatro accesos y un menú «Más».
// Ninguna opción administrativa queda inaccesible por el ancho de pantalla.
const mobileAdminMain=['daily','calendar','booking','clients'];
function mobileNav(){
 const pages=isAdmin?adminPages:clientPages;
 const primary=isAdmin?pages.filter(([p])=>mobileAdminMain.includes(p)):pages;
 const rest=isAdmin?pages.filter(([p])=>!mobileAdminMain.includes(p)):[];
 const item=([p,n,i])=>`<button type="button" data-action="go" data-page="${p}" class="${page===p?'current':''}" ${page===p?'aria-current="page"':''}><span aria-hidden="true">${i}</span><span class="nav-label">${n}</span></button>`;
 return `${isAdmin&&moreOpen?`<div class="more-backdrop" data-action="close-more" aria-hidden="true"></div><section class="more-sheet" aria-label="Más opciones de administración"><div class="more-heading"><strong>Más opciones</strong><button type="button" class="ghost compact" data-action="close-more" aria-label="Cerrar menú">✕</button></div><div class="more-grid">${rest.map(item).join('')}</div></section>`:''}<nav class="mobilebar" aria-label="Navegación principal">${primary.map(item).join('')}${isAdmin?`<button type="button" data-action="toggle-more" class="${moreOpen||rest.some(([p])=>p===page)?'current':''}" aria-expanded="${moreOpen}" aria-label="Más opciones de administración"><span aria-hidden="true">☰</span><span class="nav-label">Más</span></button>`:''}</nav>`
}
function render(){if(!user){renderAuth();return}if(busy)return;
 const pages=isAdmin?adminPages:clientPages;
 const current=page==='dashboard'?dashboard():page==='daily'?dailyPage():page==='insights'?insightsPage():page==='waitlist'?waitlistPage():page==='waiting'?clientWaitlist():page==='booking'?booking():page==='mine'?myBookings():page==='calendar'?adminCalendar():page==='clients'?clientsPage():page==='schedule'?schedulesPage():page==='treatments'?treatmentsPage():page==='payments'?paymentsPage():page==='settings'?settingsPage():page==='help'?helpPage():profilePage();
 root.innerHTML=`<div class="shell"><aside><div class="brand"><span class="flower">✿</span>masajes LUR</div><nav class="nav">${nav()}</nav><footer><span>${e(profile?.full_name||user.email)}</span><span>${isAdmin?'Administrador':'Cliente'}</span><button class="ghost compact" data-action="logout">Cerrar sesión</button></footer></aside><main class="workspace">${current}</main>${mobileNav()}</div>${modal?`<div class="modal-backdrop"><div class="modal">${modal}</div></div>`:''}`}
function renderMonth(onAction='pick-day'){const first=parseDate(shownMonth),leading=(first.getDay()+6)%7,count=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),stats=new Map(monthStats.map(s=>[s.day,s]));let html='';
 for(let i=0;i<leading;i++)html+='<div class="date blank"></div>';
 for(let d=1;d<=count;d++){const day=fmtDate(new Date(first.getFullYear(),first.getMonth(),d)),s=stats.get(day),status=!s?.total_count?'closed':!s.free_count?'full':s.free_count===s.total_count?'free':'partial';html+=`<button class="date ${status} ${day===selectedDate?'active':''} ${day<today()?'past':''}" data-action="${onAction}" data-day="${day}"><b>${d}</b><small>${s?.total_count?(s.free_count+' libres'):'Cerrado'}</small></button>`}
 return `<div class="calendar-head">${btn('prev-month','‹')}<b>${e(monthTitle(shownMonth))}</b>${btn('next-month','›')}</div><div class="days">${['L','M','X','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}</div><div class="dates">${html}</div><div class="legend"><span><i class="dot"></i> Libre</span><span><i class="dot partial"></i> Parcial</span><span><i class="dot full"></i> Completo</span><span><i class="dot closed"></i> Cerrado</span></div>`}
function treatmentSelector(){return `<label class="field">Tipo de masaje<select id="treatment-select" data-change="treatment">${activeTreatments().map(t=>`<option value="${t.id}" ${t.id===selectedTreatment?'selected':''}>${e(t.name)} · ${t.duration_minutes} min · ${money(t.price)}</option>`).join('')}</select></label>`}
function booking(){const t=currentTreatment();return `${title('Reserva tu masaje',isAdmin?'Crea una reserva para un cliente registrado o un visitante.':'Elige tratamiento, día y hora. La confirmación es inmediata.')}${isAdmin?`<div class="banner">Modo administrador: puedes registrar clientes dados de alta o citas presenciales como visitante.</div>`:''}<div class="hero"><div class="kicker">Tu momento de bienestar</div><h2>Encuentra tu próxima cita</h2><p>Los días se actualizan desde la agenda real de masajes LUR.</p></div><div class="cards two"><section class="card"><h3>1 · Elige tratamiento y fecha</h3>${treatmentSelector()}${renderMonth()}</section><section class="card"><h3>2 · Horas disponibles</h3><p class="subtle">${e(dateTitle(selectedDate))}</p>${t?`<div class="slots">${slots.filter(x=>x.available).map(x=>`<button class="slot ${chosenSlot===x.slot?'active':''}" data-action="slot" data-time="${x.slot}">${x.slot}</button>`).join('')||`<p class="empty">No quedan huecos disponibles para este masaje.</p>${!isAdmin?`<button class="ghost" data-action="join-waitlist">Avisadme si se libera una cita</button>`:''}`}</div><div class="line"></div><p class="small">${e(t.name)} · ${t.duration_minutes} minutos · ${money(t.price)}</p><p class="subtle">${chosenSlot?'Hora seleccionada: '+e(chosenSlot):'Elige una hora para continuar.'}</p>${isAdmin?`<form id="admin-book"><label class="field">Cliente registrado (opcional)<select name="client"><option value="">Visitante sin cuenta</option>${[...clients,...offlineClients].sort((a,b)=>a.full_name.localeCompare(b.full_name,'es')).map(c=>`<option value="${c.id}">${e(c.full_name||'Sin nombre')}${offlineClients.some(x=>x.id===c.id)?' · Alta manual':''}</option>`).join('')}</select></label><label class="field">Nombre del visitante (si no tiene cuenta)<input name="guest" maxlength="120" placeholder="Nombre y apellidos"></label><label class="field">Repetir la misma cita<select name="weeks"><option value="1">Solo una cita</option><option value="2">2 semanas</option><option value="4">4 semanas</option><option value="8">8 semanas</option><option value="12">12 semanas</option></select></label><button class="button" type="submit" ${!chosenSlot?'disabled':''}>Confirmar reserva</button></form>`:`<button class="button" data-action="book" ${!chosenSlot?'disabled':''}>Confirmar reserva · ${money(t.price)}</button>`}`:'<p>No hay tratamientos activos.</p>'}</section></div>`}
function myBookings(){const own=appointments.filter(a=>a.client_id===user.id).sort((a,b)=>b.day.localeCompare(a.day));return `${title('Mis citas',`Consulta tus reservas o cancela con al menos ${settings.cancel_hours} horas de antelación.`,`<button class="button compact" data-action="go" data-page="booking">+ Reservar</button>`)}<div class="card"><h3>Historial y próximas sesiones</h3>${own.length?own.map(a=>`<div class="item"><span class="time">${e(aTime(a))}</span><div class="item-main"><b>${e(a.treatment_name)}</b><p>${e(euDate(a.day))} · ${a.duration_minutes} min · ${money(a.price)}</p><span class="tag ${a.status==='cancelled'?'cancelled':''}">${a.status==='confirmed'?'Confirmada':a.status==='completed'?'Realizada':'Cancelada'}</span></div>${a.status==='confirmed'?`<button class="ghost compact" data-action="cancel-mine" data-id="${a.id}">Cancelar</button>`:''}</div>`).join(''):'<p class="empty">Todavía no tienes citas.</p>'}</div>`}
function dailyPage(){
 const rows=appointments.filter(a=>a.day===dayFocus).sort((a,b)=>aTime(a).localeCompare(aTime(b)));
 const active=rows.filter(a=>a.status!=='cancelled');
 const pending=active.filter(a=>a.payment==='unpaid');
 return `${title('Agenda diaria','Gestiona el día desde tu iPhone con un toque.',`<button class="button compact" data-action="go" data-page="booking">+ Cita</button>`)}
 <div class="daily-controls"><button class="ghost compact" data-action="daily-prev" aria-label="Día anterior">‹</button>
 <input type="date" id="daily-date" data-change="daily-date" aria-label="Fecha de agenda" value="${dayFocus}">
 <button class="ghost compact" data-action="daily-next" aria-label="Día siguiente">›</button>
 <button class="ghost compact" data-action="daily-today">Hoy</button></div>
 <div class="cards three daily-stats">${[[active.length,'Sesiones'],[pending.length,'Cobros pendientes'],[money(active.filter(a=>a.payment==='paid').reduce((v,a)=>v+Number(a.price),0)),'Cobrado ese día']].map(([n,l])=>`<div class="card"><strong>${e(n)}</strong><span>${l}</span></div>`).join('')}</div>
 <label class="field daily-search-field">Buscar cita de este día<input id="daily-search" class="search" type="search" placeholder="Nombre o tratamiento" autocomplete="off"></label><div class="daily-list">${rows.filter(a=>a.status!=='cancelled').map(a=>`<article class="daily-card" data-search-text="${e((displayName(a)+' '+a.treatment_name).toLowerCase())}"><div class="daily-time">${e(aTime(a))}<small>${a.duration_minutes} min</small></div><div class="daily-detail"><strong>${e(displayName(a))}</strong><span>${e(a.treatment_name)}</span><span>${money(a.price)} · ${a.payment==='paid'?'Cobrado':'Pendiente'}</span></div><div class="daily-actions"><button class="ghost compact" data-action="quick-reschedule" data-id="${a.id}">Mover</button><button class="ghost compact" data-action="edit-appt" data-id="${a.id}">Ficha</button>${a.status==='confirmed'?`<button class="ghost compact" data-action="quick-complete" data-id="${a.id}">Realizado</button>`:''}${a.payment==='unpaid'?`<button class="button compact" data-action="quick-paid" data-id="${a.id}">Cobrar</button>`:''}</div></article>`).join('')||'<div class="card empty">No hay sesiones este día.</div>'}</div>`;
}
function rescheduleModal(id){const a=appointments.find(x=>x.id===id);if(!a)return;
 openModal({title:'Cambiar hora de la cita',body:`<p class="subtle">${e(displayName(a))} · ${e(a.treatment_name)}. Solo se mostrarán huecos disponibles después de elegir una fecha.</p>
 <form id="quick-reschedule-form"><input type="hidden" name="id" value="${a.id}"><label class="field">Nueva fecha<input required type="date" name="day" min="${today()}" value="${a.day}"></label>
 <label class="field">Nueva hora<select name="time" required><option value="">Selecciona una fecha para cargar los huecos</option></select></label><button class="button" type="submit">Confirmar cambio</button></form>`});
 refreshMoveSlots(a.day,id);
}
async function refreshMoveSlots(day,id){const a=appointments.find(x=>x.id===id),form=$('#quick-reschedule-form');if(!form||!a)return;
 const field=form.querySelector('select[name="time"]');field.innerHTML='<option value="">Comprobando horarios…</option>';
 try{const data=await request(db.rpc('lur_availability',{p_day:day,p_treatment:a.treatment_id}));if(!form.isConnected||form.querySelector('[name="day"]').value!==day)return;
 const possible=(data||[]).filter(s=>s.available||day===a.day&&s.slot===aTime(a));
 field.innerHTML=`<option value="">Elige una hora</option>${possible.map(s=>`<option value="${e(s.slot)}" ${s.slot===aTime(a)&&day===a.day?'selected':''}>${e(s.slot)}</option>`).join('')}`;
 }catch(err){field.innerHTML='<option value="">No se pudo cargar la disponibilidad</option>';toast(readableError(err))}
}
function insightsPage(){const now=today(),month=now.slice(0,7);const visible=appointments.filter(a=>a.day.startsWith(month)),good=visible.filter(a=>a.status!=='cancelled'),cancellations=visible.filter(a=>a.status==='cancelled');
 const visits=good.filter(a=>a.status==='completed');const revenue=good.filter(a=>a.payment==='paid').reduce((n,a)=>n+Number(a.price),0);
 const incomeMonth={};const byTreatment={};const byClient={};for(const a of appointments.filter(x=>x.status!=='cancelled')){
  const key=a.day.slice(0,7);incomeMonth[key]??={paid:0,pending:0,count:0};incomeMonth[key][a.payment==='paid'?'paid':'pending']+=Number(a.price);incomeMonth[key].count++;
  if(a.day.startsWith(month)){byTreatment[a.treatment_name]=(byTreatment[a.treatment_name]||0)+1;if(a.client_id)byClient[a.client_id]=(byClient[a.client_id]||0)+1}
 }
 const max=Math.max(1,...Object.values(byTreatment));
 const repeat=Object.values(byClient).filter(n=>n>=2).length;
 return `${title('Estadísticas','Indicadores operativos según las citas registradas.')}
 <div class="cards four" style="margin-bottom:18px">${[[good.length,'Reservas este mes'],[cancellations.length,'Cancelaciones'],[money(revenue),'Marcado como cobrado'],[repeat,'Clientes con 2+ citas este mes']].map(([v,l])=>`<div class="card"><div class="stat">${e(v)}</div><p class="tiny">${l}</p></div>`).join('')}</div>
 <div class="cards equal"><section class="card"><h3>Tratamientos más solicitados · ${month}</h3>${Object.entries(byTreatment).sort((a,b)=>b[1]-a[1]).map(([n,v])=>`<div class="metric-row"><span>${e(n)}</span><b>${v}</b><div class="metric-track"><div style="width:${Math.round(v/max*100)}%"></div></div></div>`).join('')||'<p class="empty">Sin tratamientos este mes</p>'}</section>
 <section class="card"><h3>Ocupación y evolución</h3><p class="small">Citas realizadas este mes: ${visits.length}. Canceladas: ${cancellations.length}.</p><div class="tablewrap"><table class="table"><thead><tr><th>Mes</th><th>Citas</th><th>Cobrado</th><th>Pendiente</th></tr></thead><tbody>${Object.entries(incomeMonth).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,12).map(([m,v])=>`<tr><td>${m}</td><td>${v.count}</td><td>${money(v.paid)}</td><td>${money(v.pending)}</td></tr>`).join('')}</tbody></table></div><p class="help">Las cifras se calculan con las citas cargadas en la aplicación (máximo 3000), no constituyen una contabilidad fiscal.</p></section></div>`;
}
function clientWaitlist(){const own=waitlist.filter(w=>w.client_id===user.id);return `${title('Lista de espera','Solicita un aviso si se cancela una cita. No te asigna una reserva automáticamente.')}
 <section class="card"><h3>Mis solicitudes</h3>${own.map(w=>`<div class="item"><div class="item-main"><b>${e(euDate(w.day))} · ${e(trName(w.treatment_id))}</b><p>${w.status==='waiting'?'Esperando hueco':w.status==='notified'?'Aviso generado':'Solicitud cancelada'}</p></div>${w.status!=='cancelled'?btn('leave-waitlist','Salir','data-id="'+w.id+'"'):''}</div>`).join('')||'<p class="empty">Todavía no estás en ninguna lista de espera.</p>'}</section>`}
function waitlistPage(){const rows=waitlist.filter(w=>w.status!=='cancelled');return `${title('Lista de espera','Clientes interesados por día y tratamiento. El aviso no garantiza disponibilidad.')}<section class="card">${rows.map(w=>`<div class="item"><div class="item-main"><b>${e(customer(w.client_id)?.full_name||'Cliente')}</b><p>${e(euDate(w.day))} · ${e(trName(w.treatment_id))} · ${w.status==='waiting'?'En espera':'Avisado'}</p></div></div>`).join('')||'<p class="empty">Sin solicitudes activas.</p>'}</section>`}
function dashboard(){const upcoming=appointments.filter(a=>a.status==='confirmed'&&a.day>=today()).sort((a,b)=>(a.day+aTime(a)).localeCompare(b.day+aTime(b)));const todays=dayAppts(today()),paid=appointments.filter(a=>a.payment==='paid'&&a.status!=='cancelled');return `${title('Panel de inicio','Información de las reservas de tu centro',`<button class="button compact" data-action="go" data-page="booking">+ Nueva cita</button>`)}<div class="cards four" style="margin-bottom:18px">${[[todays.length,'Citas hoy'],[upcoming.length,'Próximas'],[clients.length+offlineClients.length,'Clientes'],[money(paid.reduce((v,a)=>v+Number(a.price),0)),'Total cobrado registrado']].map(([n,l])=>`<div class="card"><div class="stat">${e(n)}</div><p class="tiny">${l}</p></div>`).join('')}</div><div class="actions" style="margin-bottom:18px"><button class="button" data-action="go" data-page="daily">Abrir agenda diaria</button><button class="ghost" data-action="go" data-page="insights">Ver estadísticas</button></div><div class="cards two"><section class="card"><h3>Próximas citas</h3>${upcoming.slice(0,10).map(a=>appointmentRow(a)).join('')||'<p class="empty">No hay reservas próximas.</p>'}</section><section class="card"><h3>Agenda de hoy</h3>${todays.map(a=>appointmentRow(a)).join('')||'<p class="empty">Hoy no hay reservas.</p>'}</section></div>`}
function appointmentRow(a){return `<div class="item"><span class="time">${e(aTime(a))}</span><div class="item-main"><b>${e(displayName(a))}</b><p>${e(euDate(a.day))} · ${e(a.treatment_name)} · ${money(a.price)}</p><span class="tag ${a.status==='cancelled'?'cancelled':a.payment==='unpaid'?'pending':''}">${a.status==='cancelled'?'Cancelada':a.status==='completed'?'Realizada':'Confirmada'} · ${a.payment==='paid'?'Pagado':'Pendiente'}</span></div><button class="ghost compact" data-action="edit-appt" data-id="${a.id}">Editar</button></div>`}
function adminCalendar(){const appts=appointments.filter(a=>a.day===selectedDay).sort((a,b)=>aTime(a).localeCompare(aTime(b)));return `${title('Agenda de masajes','Calendario mensual o semanal con citas y ocupación.')}<div class="actions" style="margin-bottom:18px"><button class="${calendarMode==='month'?'button':'ghost'} compact" data-action="cal-mode" data-mode="month">Mes</button><button class="${calendarMode==='week'?'button':'ghost'} compact" data-action="cal-mode" data-mode="week">Semana</button><button class="ghost compact" data-action="go" data-page="daily">Vista diaria</button></div>${calendarMode==='month'?`<div class="cards two"><section class="card">${renderMonth('admin-day')}</section><section class="card"><h3>${e(dateTitle(selectedDay))}</h3>${appts.map(a=>appointmentRow(a)).join('')||'<div class="empty">No hay citas</div>'}<button class="ghost compact" data-action="book-on-selected">+ Reservar este día</button></section></div>`:weekCalendar()}`}
function weekCalendar(){const p=parseDate(activeWeek),dayNumber=(p.getDay()+6)%7,start=plusDays(activeWeek,-dayNumber),dates=Array.from({length:7},(_,i)=>plusDays(start,i)),t=currentTreatment()||{duration_minutes:60,buffer_minutes:0};let result='<div class="card"><div class="calendar-head">'+btn('week-prev','‹')+`<b>Semana del ${e(euDate(start))}</b>`+btn('week-next','›')+'</div><div class="tablewrap"><div class="week"><div class="head">Hora</div>'+dates.map(d=>`<div class="head">${e(euDate(d).slice(0,7))}</div>`).join('');for(let t0=8*60;t0<22*60;t0+=30){const t=hhmm(t0);result+=`<div class="head">${t}</div>`;for(const d of dates){const busyApp=dayAppts(d).find(a=>overlaps(t0,t0+30,mins(aTime(a)),mins(aTime(a))+a.duration_minutes+a.buffer_minutes)),open=adminSlots(d,t).some(x=>x.slot===t&&x.available);result+=`<button class="cell ${busyApp?'busy':open?'':'closed'}" data-action="${busyApp?'edit-appt':'book-week'}" ${busyApp?`data-id="${busyApp.id}"`:`data-day="${d}" data-time="${t}"`} ${!busyApp&&!open?'disabled':''}>${busyApp?e(displayName(busyApp)):(open?'+':'—')}</button>`}}return result+'</div></div></div>'}
function clientsPage(){const all=[...clients.map(c=>({...c,kind:'account'})),...offlineClients.map(c=>({...c,kind:'offline'}))].sort((a,b)=>a.full_name.localeCompare(b.full_name,'es'));const rows=all.filter(x=>(x.full_name+' '+(x.phone||'')+' '+(x.email||'')).toLowerCase().includes(search.toLowerCase()));return `${title('Clientes','Clientes registrados y fichas añadidas por administración.',`<button class="button compact" data-action="new-client">+ Nuevo cliente</button>`)}<section class="card"><input class="search" id="client-search" placeholder="Buscar por nombre, correo o teléfono" value="${e(search)}"><div class="tablewrap clients-table"><table class="table"><thead><tr><th>Cliente</th><th>Correo</th><th>Teléfono</th><th>Tipo</th><th>Citas</th><th>Acciones</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${e(c.full_name)}</td><td>${e(c.email||'—')}</td><td>${e(c.phone||'—')}</td><td>${c.kind==='offline'?'Alta manual':'Con cuenta'}</td><td>${appointments.filter(a=>appointmentClient(a)===c.id).length}</td><td><button class="ghost compact" data-action="client-details" data-id="${c.id}">Ver ficha</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="empty">No hay clientes.</p>':''}</section>`}

function schedulesPage(){const wins=getSchedule(scheduleDate),selectedOverride=schedules.find(s=>s.day===scheduleDate);return `${title('Horarios','Personaliza cada día del calendario. Por defecto: lunes a viernes, 17:00–20:00.') }<div class="cards two"><section class="card">${renderMonth('schedule-day')}</section><section class="card"><h3>Horario · ${e(euDate(scheduleDate))}</h3><p class="subtle">${selectedOverride?'Horario personalizado':'Horario predeterminado'}</p><form id="schedule-form"><label class="field">Estado<select name="status" id="schedule-status"><option value="open" ${wins.length?'selected':''}>Abierto</option><option value="closed" ${!wins.length?'selected':''}>Cerrado</option></select></label><div class="form-row"><label class="field">Tramo 1: apertura<input name="start1" type="time" step="1800" value="${wins[0]?.start||'17:00'}"></label><label class="field">Tramo 1: cierre<input name="end1" type="time" step="1800" value="${wins[0]?.end||'20:00'}"></label></div><div class="form-row"><label class="field">Tramo 2: apertura<input name="start2" type="time" step="1800" value="${wins[1]?.start||''}"></label><label class="field">Tramo 2: cierre<input name="end2" type="time" step="1800" value="${wins[1]?.end||''}"></label></div><div class="actions"><button class="button" type="submit">Guardar este día</button>${selectedOverride?btn('reset-schedule','Restaurar predeterminado'):''}</div></form><div class="line"></div><h3>Copiar este horario</h3><form id="copy-schedule-form"><label class="field">Hasta la fecha<input type="date" name="until" value="${plusDays(scheduleDate,7)}" required></label><label class="field" style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="weekdays" style="width:auto" checked>Solo lunes a viernes</label><button type="submit" class="ghost">Aplicar a las fechas seleccionadas</button></form><p class="small" style="margin-top:12px">Los cambios de horario conservan las citas existentes. Revísalas si cierras un día con reservas.</p></section></div>`}
function treatmentsPage(){return `${title('Tratamientos','Precios y duraciones que se muestran a los clientes.',`<button class="button compact" data-action="new-treatment">+ Añadir</button>`)}<section class="card"><div class="tablewrap"><table class="table"><thead><tr><th>Tratamiento</th><th>Duración</th><th>Preparación</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody>${treatments.map(t=>`<tr><td><b>${e(t.name)}</b></td><td>${t.duration_minutes} min</td><td>${t.buffer_minutes} min</td><td>${money(t.price)}</td><td>${t.active?'Activo':'Inactivo'}</td><td><button class="ghost compact" data-action="edit-treatment" data-id="${t.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></section>`}
function paymentsPage(){const valid=appointments.filter(a=>a.status!=='cancelled'),paid=valid.filter(a=>a.payment==='paid'),unpaid=valid.filter(a=>a.payment==='unpaid'),total=rows=>rows.reduce((v,a)=>v+Number(a.price||0),0);const byMonth={};valid.forEach(a=>{let k=a.day.slice(0,7);byMonth[k]??={paid:0,pending:0};byMonth[k][a.payment==='paid'?'paid':'pending']+=Number(a.price)});return `${title('Cobros','Control administrativo; no realiza cargos bancarios.') }<div class="cards three" style="margin-bottom:17px">${[[money(total(paid)),'Total marcado como pagado'],[money(total(unpaid)),'Importe pendiente'],[valid.length,'Citas no canceladas']].map(([v,l])=>`<div class="card"><div class="money">${v}</div><p class="tiny">${l}</p></div>`).join('')}</div><section class="card"><h3>Resumen mensual</h3><div class="tablewrap"><table class="table"><thead><tr><th>Mes</th><th>Pagado</th><th>Pendiente</th></tr></thead><tbody>${Object.entries(byMonth).sort((a,b)=>b[0].localeCompare(a[0])).map(([m,v])=>`<tr><td>${e(m)}</td><td>${money(v.paid)}</td><td>${money(v.pending)}</td></tr>`).join('')}</tbody></table></div></section><p class="subtle">Los ingresos corresponden al estado de pago de las citas; no sustituyen una contabilidad fiscal ni registran devoluciones.</p>`}
function settingsPage(){return `${title('Configuración del negocio','Política de cancelación y contacto para los clientes.')}<div class="card" style="max-width:660px"><form id="business-settings-form"><label class="field">Antelación para cancelar una cita<select name="cancel_hours">${[0,12,24,48,72,96,168].map(h=>`<option value="${h}" ${settings.cancel_hours===h?'selected':''}>${h} horas</option>`).join('')}</select></label><label class="field">Teléfono público de contacto<input name="business_phone" type="tel" maxlength="40" value="${e(settings.business_phone)}" placeholder="Ej.: +34 600 000 000"></label><label class="field">Correo público de contacto<input name="business_email" type="email" maxlength="150" value="${e(settings.business_email)}" placeholder="contacto@ejemplo.com"></label><button class="button" type="submit">Guardar configuración</button></form><div class="line"></div><p class="small">La conexión a Supabase se configura en config.js y no se muestra en el panel del cliente. Los permisos de administrador se asignan en Supabase.</p><p class="small">Los recordatorios por correo y WhatsApp se preparan manualmente desde la ficha de cada cita. El envío automático requiere configurar un proveedor externo.</p></div>`}
function helpPage(){let phone=String(settings.business_phone||'').replace(/\D/g,'');return `${title('Ayuda y contacto','¿Necesitas cambiar una cita o tienes alguna consulta?')}<div class="card"><h3>Contacta con masajes LUR</h3><p class="subtle">Puedes cancelar desde Mis citas hasta ${settings.cancel_hours} horas antes. Después contacta con el centro.</p><div class="actions">${phone?`<a class="button" href="https://wa.me/${e(phone)}" target="_blank" rel="noopener noreferrer">Escribir por WhatsApp</a>`:''}${settings.business_email?`<a class="ghost" href="mailto:${e(settings.business_email)}">Enviar un correo</a>`:''}</div>${!phone&&!settings.business_email?'<p>El centro todavía no ha configurado sus datos de contacto.</p>':''}</div>`}
function profilePage(){return `${title('Mi perfil','Actualiza tus datos de contacto y acceso.') }<div class="cards two"><section class="card"><h3>Datos personales</h3><form id="profile-form"><label class="field">Nombre y apellidos<input name="name" value="${e(profile?.full_name||'')}" maxlength="120" required></label><label class="field">Teléfono<input name="phone" type="tel" value="${e(profile?.phone||'')}" maxlength="40" required></label><label class="field">Correo electrónico<input value="${e(user.email||'')}" disabled></label><p class="subtle">Para cambiar tu correo, utiliza el formulario de abajo; necesitarás confirmar el cambio.</p><button class="button" type="submit">Guardar mis datos</button></form></section><section class="card"><h3>Seguridad</h3><form id="email-form"><label class="field">Nuevo correo electrónico<input name="email" type="email" autocomplete="email" required></label><button class="ghost" type="submit">Solicitar cambio de correo</button></form><div class="line"></div><form id="password-form"><label class="field">Nueva contraseña<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><button class="ghost" type="submit">Cambiar contraseña</button></form><div class="line"></div><p class="small">${isAdmin?'Tienes permisos de administración. La conexión de Supabase se configura exclusivamente en config.js.':'Tu cuenta solo permite ver tus datos y tus propias citas.'}</p><button class="ghost" data-action="logout" style="margin-top:15px">Cerrar sesión</button></section></div>`}
function openModal(html){modal=`<div class="modal-head"><h2>${html.title}</h2><button class="ghost compact" data-action="close-modal">Cerrar</button></div>${html.body}`;render()}
function closeModal(){modal=null;render()}
function editAppointment(id){const a=appointments.find(x=>x.id===id);if(!a)return;const related=customer(appointmentClient(a));openModal({title:'Gestionar cita',body:`<p class="subtle">${e(displayName(a))} · ${e(a.treatment_name)}</p><form id="edit-appointment-form"><input type="hidden" name="id" value="${a.id}"><div class="form-row"><label class="field">Fecha<input name="day" type="date" value="${a.day}" required></label><label class="field">Hora<input name="time" type="time" step="1800" value="${e(aTime(a))}" required></label></div><div class="form-row"><label class="field">Estado<select name="status">${[['confirmed','Confirmada'],['completed','Realizada'],['cancelled','Cancelada']].map(([v,l])=>`<option value="${v}" ${a.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Cobro<select name="payment"><option value="unpaid" ${a.payment==='unpaid'?'selected':''}>Pendiente</option><option value="paid" ${a.payment==='paid'?'selected':''}>Pagado</option></select></label></div><label class="field">Precio de esta cita (€)<input name="price" type="number" min="0" step=".01" value="${Number(a.price)}" required></label><label class="field">Observaciones administrativas<textarea name="notes" maxlength="1500">${e(a.notes)}</textarea></label><div class="actions"><button class="button" type="submit">Guardar cambios</button>${related?.phone?`<button type="button" class="ghost" data-action="whatsapp" data-id="${a.id}">WhatsApp</button>`:''}${related?.email?`<button type="button" class="ghost" data-action="email-reminder" data-id="${a.id}">Correo</button>`:''}</div></form><p class="small" style="margin-top:12px">Modificar el precio histórico no altera los precios estándar. Para cambiar hora se comprueba la restricción de solapamiento en la base de datos.</p>`})}
function editTreatment(id){const t=treatments.find(x=>x.id===id)||{id:'',name:'',duration_minutes:60,buffer_minutes:0,price:40,active:true};openModal({title:t.id?'Editar tratamiento':'Nuevo tratamiento',body:`<form id="treatment-form"><input type="hidden" name="id" value="${t.id}"><label class="field">Nombre<input name="name" maxlength="100" value="${e(t.name)}" required></label><div class="form-row"><label class="field">Duración<select name="duration">${[30,60,90,120,150,180,210,240].map(n=>`<option value="${n}" ${n===t.duration_minutes?'selected':''}>${n} minutos</option>`).join('')}</select></label><label class="field">Preparación entre citas<select name="buffer">${[0,30,60,90,120].map(n=>`<option value="${n}" ${n===t.buffer_minutes?'selected':''}>${n} minutos</option>`).join('')}</select></label></div><label class="field">Precio estándar (€)<input type="number" step=".01" min="0" max="999999" name="price" value="${t.price}" required></label><label class="field">Disponibilidad<select name="active"><option value="true" ${t.active?'selected':''}>Visible para reservar</option><option value="false" ${!t.active?'selected':''}>No disponible</option></select></label><button class="button" type="submit">Guardar tratamiento</button></form>`})}
function newClient(){openModal({title:'Nuevo cliente',body:`<form id="offline-client-form"><label class="field">Nombre y apellidos<input name="name" maxlength="120" required autocomplete="off" placeholder="Nombre del cliente"></label><label class="field">Correo electrónico (opcional)<input name="email" type="email" maxlength="150" autocomplete="off" placeholder="Se puede añadir más adelante"></label><label class="field">Teléfono (opcional)<input name="phone" type="tel" maxlength="40" autocomplete="off" placeholder="Se puede añadir más adelante"></label><button class="button" type="submit">Guardar cliente</button></form><p class="small" style="margin-top:12px">No crea una cuenta de acceso ni envía correos. Se puede reservar una cita a su nombre.</p>`})}
function clientDetails(id){const c=customer(id);if(!c)return;const offline=offlineClients.some(x=>x.id===id);const hist=appointments.filter(a=>appointmentClient(a)===id).sort((a,b)=>b.day.localeCompare(a.day));openModal({title:'Ficha de cliente',body:`<p class="small">${offline?'Alta manual sin cuenta':'Cliente registrado con cuenta de acceso'}</p><form id="client-form"><input type="hidden" name="id" value="${c.id}"><label class="field">Nombre<input name="name" value="${e(c.full_name)}" maxlength="120" required></label>${offline?`<label class="field">Correo electrónico (opcional)<input name="email" type="email" maxlength="150" value="${e(c.email||'')}"></label>`:`<p class="small">Correo asociado a la cuenta: ${e(c.email||'—')} (no se cambia desde aquí).</p>`}<label class="field">Teléfono (opcional)<input name="phone" type="tel" value="${e(c.phone||'')}" maxlength="40"></label><button type="submit" class="button">Guardar datos</button></form><div class="line"></div><h3>Historial de citas</h3>${hist.map(a=>`<div class="item"><span class="time">${e(euDate(a.day))}</span><div class="item-main"><b>${e(a.treatment_name)}</b><p>${e(aTime(a))} · ${money(a.price)} · ${e(a.status)}</p></div><button class="ghost compact" data-action="edit-appt" data-id="${a.id}">Editar</button></div>`).join('')||'<div class="empty">Sin citas</div>'}`})}

function mailReminder(a){const c=customer(appointmentClient(a));if(!c?.email){toast('Este cliente no tiene correo');return}const subject='Recordatorio de tu cita en masajes LUR';const msg=`Hola ${c.full_name}, te recordamos tu masaje de ${a.treatment_name} el ${euDate(a.day)} a las ${aTime(a)}. Gracias.`;window.location.href=`mailto:${encodeURIComponent(c.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(msg)}`}
function phoneWhatsApp(a){const c=customer(appointmentClient(a));const phone=String(c?.phone||'').replace(/\D/g,'');if(!phone){toast('Este cliente no tiene teléfono');return}const msg=`Hola ${c.full_name}, te confirmamos tu masaje en masajes LUR el ${euDate(a.day)} a las ${aTime(a)}. ¡Gracias!`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer')}
async function writeOperation(label,fn){if(saving)return;saving=true;try{await fn();modal=null;toast(label);await loadData(true)}catch(err){toast(readableError(err));saving=false;render()}finally{saving=false}}
async function changeView(next){page=next;moreOpen=false;modal=null;render();if(next==='booking'){await fetchSlots();render()}}
async function clickHandler(event){const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,day=b.dataset.day;
 try{switch(a){
 case 'auth-mode':loginMode=b.dataset.mode;authError='';renderAuth();break;
 case 'go':await changeView(b.dataset.page);break;
 case 'toggle-more':moreOpen=!moreOpen;render();break;
 case 'close-more':moreOpen=false;render();break;
 case 'logout':stopRealtime();await db?.auth.signOut();user=null;profile=null;isAdmin=false;loginMode='signin';renderAuth();break;
 case 'retry':await loadData(true);break;
 case 'daily-prev':dayFocus=plusDays(dayFocus,-1);render();break;
 case 'daily-next':dayFocus=plusDays(dayFocus,1);render();break;
 case 'daily-today':dayFocus=today();render();break;
 case 'quick-reschedule':if(isAdmin)rescheduleModal(id);break;
 case 'quick-paid':if(isAdmin)await writeOperation('Pago registrado',()=>request(db.from('lur_appointments').update({payment:'paid'}).eq('id',id)));break;
 case 'quick-complete':if(isAdmin)await writeOperation('Cita marcada como realizada',()=>request(db.from('lur_appointments').update({status:'completed'}).eq('id',id)));break;
 case 'join-waitlist':if(isAdmin)break;if(!selectedTreatment)throw Error('Elige un tratamiento');await writeOperation('Inscripción en lista de espera confirmada',()=>request(db.rpc('lur_join_waitlist',{p_day:selectedDate,p_treatment:selectedTreatment})));page='waiting';break;
 case 'leave-waitlist':if(!confirm('¿Salir de esta lista de espera?'))break;await writeOperation('Solicitud eliminada',()=>request(db.rpc('lur_leave_waitlist',{p_id:id})));break;
 case 'prev-month':shownMonth=addMonth(shownMonth,-1);await fetchCalendar();render();break;
 case 'next-month':shownMonth=addMonth(shownMonth,1);await fetchCalendar();render();break;
 case 'pick-day':selectedDate=day;chosenSlot='';await fetchSlots();render();break;
 case 'slot':chosenSlot=b.dataset.time;render();break;
 case 'book':if(!chosenSlot){toast('Selecciona una hora');break}if(!confirm(`¿Confirmar la cita de ${trName(selectedTreatment)} el ${euDate(selectedDate)} a las ${chosenSlot}?`))break;await writeOperation('Reserva confirmada',async()=>{await request(db.rpc('lur_book',{p_day:selectedDate,p_time:chosenSlot,p_treatment:selectedTreatment}));page='mine'});break;
 case 'cancel-mine':if(confirm(`¿Cancelar esta cita? Solo es posible con al menos ${settings.cancel_hours} horas de antelación.`))await writeOperation('Cita cancelada',()=>request(db.rpc('lur_cancel',{p_appointment:id})));break;
 case 'admin-day':selectedDay=day;selectedDate=day;render();break;
 case 'cal-mode':calendarMode=b.dataset.mode;render();break;
 case 'week-prev':activeWeek=plusDays(activeWeek,-7);render();break;
 case 'week-next':activeWeek=plusDays(activeWeek,7);render();break;
 case 'book-week':selectedDate=day;chosenSlot=b.dataset.time;page='booking';shownMonth=day.slice(0,7)+'-01';await fetchCalendar();await fetchSlots();render();break;
 case 'book-on-selected':selectedDate=selectedDay;chosenSlot='';page='booking';await fetchSlots();render();break;
 case 'edit-appt':editAppointment(id);break;
 case 'edit-treatment':editTreatment(id);break;
 case 'new-treatment':editTreatment(null);break;
 case 'client-details':clientDetails(id);break;
 case 'new-client':if(!isAdmin)throw Error('Acceso reservado');newClient();break;
 case 'close-modal':closeModal();break;
 case 'whatsapp':phoneWhatsApp(appointments.find(x=>x.id===id));break;
 case 'email-reminder':mailReminder(appointments.find(x=>x.id===id));break;
 case 'schedule-day':scheduleDate=day;selectedDate=day;render();break;
 case 'reset-schedule':if(!confirm(`¿Restaurar el horario predeterminado del ${euDate(scheduleDate)}? Las citas existentes se conservarán.`))break;await writeOperation('Horario restaurado',()=>request(db.from('lur_schedules').delete().eq('day',scheduleDate)));break;
 default:break;
 }}catch(err){toast(readableError(err))}}
async function changeHandler(event){const el=event.target;if(el.id==='daily-date'){dayFocus=el.value;render();return}if(el.name==='day'&&el.closest('#quick-reschedule-form')){await refreshMoveSlots(el.value,el.closest('form').querySelector('[name=id]').value);return}if(el.dataset.change==='treatment'){selectedTreatment=el.value;chosenSlot='';try{await fetchCalendar();await fetchSlots();render()}catch(err){toast(readableError(err))}}}
function validateWindows(raw){if(raw.status==='closed')return[];const pairs=[[raw.start1,raw.end1],[raw.start2,raw.end2]],result=[];for(const [a,b] of pairs){if(!a&&!b)continue;if(!a||!b)throw Error('Completa ambos extremos de cada tramo');if(mins(a)>=mins(b))throw Error('La apertura debe ser anterior al cierre');if(mins(a)%30||mins(b)%30)throw Error('Solo se admiten medias horas');result.push({start:a,end:b})}if(!result.length)throw Error('Indica al menos un tramo');result.sort((x,y)=>x.start.localeCompare(y.start));if(result.length>1&&result[0].end>result[1].start)throw Error('Los tramos se solapan');return result}
async function submitHandler(ev){const form=ev.target;const formId=form.getAttribute('id');if(!formId)return;ev.preventDefault();const data=Object.fromEntries(new FormData(form));try{switch(formId){
 case 'auth-form':{
  authError='';const email=data.email.trim(),password=data.password||'';
  if(loginMode==='signup'){
   if(data.name.trim().length<2||data.phone.trim().length<5)throw Error('Completa correctamente nombre y teléfono');
   const {data:r,error}=await db.auth.signUp({email,password,options:{data:{full_name:data.name.trim(),phone:data.phone.trim()},emailRedirectTo:window.location.origin+window.location.pathname}});if(error)throw error;
   if(r.session?.user)await boot(r.session.user);else{loginMode='signin';authError='Comprueba tu correo y confirma tu cuenta antes de entrar.';renderAuth()}
  }else if(loginMode==='recover'){
   await request(db.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin+window.location.pathname}));loginMode='signin';authError='Si el correo está registrado, recibirás instrucciones para recuperar el acceso.';renderAuth();
  }else{const {data:r,error}=await db.auth.signInWithPassword({email,password});if(error)throw error;await boot(r.user)}
  break;}
 case 'quick-reschedule-form':{
  if(!isAdmin)throw Error('Acceso reservado');const a=appointments.find(x=>x.id===data.id);if(!a)throw Error('Cita no encontrada');
  if(!data.day||!data.time)throw Error('Elige un día y una hora disponible');
  await writeOperation('Cita reprogramada',()=>request(db.rpc('lur_admin_update_appointment',{p_id:a.id,p_day:data.day,p_time:data.time,p_status:a.status,p_payment:a.payment,p_price:Number(a.price),p_notes:a.notes||''})));break;}
 case 'business-settings-form':if(!isAdmin)throw Error('Acceso reservado');await writeOperation('Ajustes guardados',()=>request(db.from('lur_business_settings').update({cancel_hours:Number(data.cancel_hours),business_phone:data.business_phone.trim(),business_email:data.business_email.trim()}).eq('id',1)));break;
 case 'profile-form':await writeOperation('Perfil actualizado',()=>request(db.from('lur_profiles').update({full_name:data.name.trim(),phone:data.phone.trim(),updated_at:new Date().toISOString()}).eq('id',user.id)));break;
 case 'email-form':await writeOperation('Revisa tu correo para confirmar el cambio',()=>request(db.auth.updateUser({email:data.email.trim()})));break;
 case 'password-form':await writeOperation('Contraseña cambiada',()=>request(db.auth.updateUser({password:data.password})));break;
 case 'treatment-form':{
  if(!isAdmin)throw Error('Acceso reservado');const values={name:data.name.trim(),duration_minutes:Number(data.duration),buffer_minutes:Number(data.buffer),price:Number(data.price),active:data.active==='true'};
  await writeOperation('Tratamiento guardado',()=>request(data.id?db.from('lur_treatments').update(values).eq('id',data.id):db.from('lur_treatments').insert(values)));break;}
 case 'offline-client-form':{
  if(!isAdmin)throw Error('Acceso reservado');if(data.name.trim().length<2)throw Error('Introduce un nombre válido');
  await writeOperation('Cliente creado',()=>request(db.from('lur_offline_clients').insert({full_name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim()})));break;}
 case 'client-form':{
  if(!isAdmin)throw Error('Acceso reservado');if(data.name.trim().length<2)throw Error('Introduce un nombre válido');
  if(offlineClients.some(x=>x.id===data.id))await writeOperation('Cliente actualizado',()=>request(db.from('lur_offline_clients').update({full_name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim(),updated_at:new Date().toISOString()}).eq('id',data.id)));
  else await writeOperation('Cliente actualizado',()=>request(db.from('lur_profiles').update({full_name:data.name.trim(),phone:data.phone.trim(),updated_at:new Date().toISOString()}).eq('id',data.id)));
  break;}
 case 'admin-book':{
  if(!isAdmin)throw Error('Acceso reservado');if(!chosenSlot)throw Error('Elige una hora');if(!data.client&&!data.guest.trim())throw Error('Elige un cliente o escribe el nombre del visitante');if(!confirm(`¿Confirmar ${data.weeks} cita(s) comenzando el ${euDate(selectedDate)} a las ${chosenSlot}?`))break;
  await writeOperation('Cita(s) confirmada(s)',()=>request(db.rpc('lur_admin_repeat_book_with_offline',{p_day:selectedDate,p_time:chosenSlot,p_treatment:selectedTreatment,p_client:clients.some(c=>c.id===data.client)?data.client:null,p_offline_client:offlineClients.some(c=>c.id===data.client)?data.client:null,p_guest:data.guest||null,p_weeks:Number(data.weeks)})));break;}
 case 'schedule-form':{
  if(!isAdmin)throw Error('Acceso reservado');const windows=validateWindows(data);if(dayAppts(scheduleDate).length&&!confirm('Este día ya tiene citas. No se borrarán aunque el horario nuevo las deje fuera. ¿Guardar?'))break;
  await writeOperation('Horario guardado',()=>request(db.from('lur_schedules').upsert({day:scheduleDate,windows,updated_at:new Date().toISOString()})));break;}
 case 'copy-schedule-form':{
  if(!isAdmin)throw Error('Acceso reservado');const source=getSchedule(scheduleDate);let days=[];for(let d=plusDays(scheduleDate,1);d<=data.until;d=plusDays(d,1)){days.push(d);if(days.length>93)throw Error('Máximo 93 días para copiar horarios')}if(data.weekdays)days=days.filter(isWorkday);if(!days.length)throw Error('No hay fechas para copiar');if(!confirm(`Aplicar horario a ${days.length} días? Las citas actuales se conservarán.`))break;
  await writeOperation('Horarios copiados',()=>request(db.from('lur_schedules').upsert(days.map(day=>({day,windows:source,updated_at:new Date().toISOString()})))));break;}
 case 'edit-appointment-form':{
  if(!isAdmin)throw Error('Acceso reservado');const old=appointments.find(a=>a.id===data.id);if(!old)throw Error('Cita no encontrada');const day=data.day,at=data.time;
  if(!parseDate(day)||!/^\d\d:(00|30)$/.test(at))throw Error('Fecha u hora incorrecta');
  const changed=old.day!==day||aTime(old)!==at;
  const start=`${day}T${at}:00`,endDay=plusDays(day,0);
  const startMinute=mins(at),total=startMinute+old.duration_minutes+old.buffer_minutes;
  if(total>=1440)throw Error('La cita no puede cruzar la medianoche');
  const ends=`${endDay}T${hhmm(total)}:00`;
  const values={day,start_time:at,starts_at:start,ends_at:ends,status:data.status,payment:data.payment,price:Number(data.price),notes:data.notes||''};
  if(changed&&old.status==='cancelled'&&data.status==='cancelled'){} // solo se reserva al reactivar
  await writeOperation('Cita actualizada',()=>request(db.rpc('lur_admin_update_appointment',{p_id:old.id,p_day:day,p_time:at,p_status:data.status,p_payment:data.payment,p_price:Number(data.price),p_notes:data.notes||''})));break;}
 }}catch(err){if(formId==='auth-form'){authError=readableError(err);renderAuth()}else toast(readableError(err))}}
root.addEventListener('click',clickHandler);root.addEventListener('change',changeHandler);root.addEventListener('submit',submitHandler);
root.addEventListener('input',ev=>{if(ev.target.id==='daily-search'){const term=ev.target.value.trim().toLowerCase();root.querySelectorAll('.daily-card').forEach(card=>{card.hidden=!card.dataset.searchText.includes(term)});return}if(ev.target.id==='client-search'){search=ev.target.value;const cursor=ev.target.selectionStart;render();const field=$('#client-search');if(field){field.focus();field.setSelectionRange(cursor,cursor)}}});
window.addEventListener('online',()=>{if(user)refreshQuiet()});
init();
